import type { Method } from '../ipc/api.js';

/**
 * What external agents may reach of the API: every method (src/ipc/api.ts) is decided here. The type
 * is `Record<Method, …>`, so a new method doesn't compile until someone decides. The external server
 * never forwards to these methods: its tools call ports of their own, one named method each.
 *
 * `covered`: a tool does this, under the decision table.
 * `gated`: a tool does this after one card, at every level, with no Always (BLG-244).
 * `ui_only`: it has no meaning without a screen. It does not change what Beluga keeps or read data for a caller.
 * `refused`: no tool, for the reason it gives.
 */
export type ExternalAccess = 'covered' | 'gated' | 'ui_only' | { readonly refused: string };

const APPROVALS = 'An approval is a person\'s answer: no agent says yes to a step or a request.';
const GRANTS = 'An agent never reads or changes a grant, its own or another agent\'s.';
const SECRET_VALUES = 'It holds or returns a secret value.';
const ENV_LIST = 'It replaces the whole list of variables, and an agent cannot read the values it would have to keep.';
const PAIRING = 'A person pairs a phone, with the phone in hand.';
const SIGN_IN = 'A sign-in is a person\'s, in a browser.';
const PHONE_LINK = 'The phone\'s own link: an agent uses the chat, file and board tools for the same work.';
const YOUR_MAC = 'The owner gave agents the sidebar\'s chats, not the Your Mac chats (BLG-243).';
const OTHERS_RUNS = 'It stops runs that are not this agent\'s: beluga_chat_interrupt stops its own.';
const INBOX = 'The inbox marks what a person has read, and an agent\'s mark would hide it from them.';
const NO_SCOPE = 'A file name does not say which chat the image is in, so a grant cannot check it.';
const VIEW_SOURCE = 'It runs a view\'s source, which can be a command: sentinel_try_source tries one under its own class.';
const AGENT_TERM = 'A terminal app for a person to type in: an agent works through beluga_chat_send.';
const STATS = 'The Usage tab counts the person\'s work in every project, past any grant\'s scope.';
const WEB_SESSION = 'A browser session can answer approvals and read secret values, which no agent does (BLG-244).';
const WINDOW_LOAD = 'The window notes a part of itself that did not load: an agent has no window.';
const PREVIEW = 'A live preview is built for a window\'s frame and drawn there: an agent has no frame.';
const MCP_APP = 'An MCP App is drawn in a window\'s frame: an agent has no frame.';
const SAVE_PANEL = 'It writes a file where a person chose in the Save panel.';
const COMPUTERS = 'It manages your other computers, or moves work between them: a person does that from the app.';
const NO_TOOL = 'No tool reaches it yet: a tool for it comes with its own decision.';

